preConditionHook:
// THE MARGINAL THREE-PUSH THAT BREAKS OUT WITH THE PUSHES. Each new extreme
// beats the one before it by only a tick or two -- a wedge made of minor
// breakouts -- and the bar CLOSES beyond the last push's extreme rather
// than reversing out of it. The long is three pushes UP followed by a close
// above the newest swing high; the short is the mirror on the lows.
//
// THE OPPOSITE TRADE to ThreePushSwingBreakoutEntry, which takes three pushes
// DOWN and buys the close through the newest swing high -- the break of the
// wedge's other side, against the pushes. This one goes WITH them. Same
// primitive, different bars, so both are kept.
//
// NOT ThreePushPattern at shapeMode = 1: that mode compares the two
// increments with each other (the later push extending LESS than the earlier
// one), a converging shape at any size. This caps EACH increment in TICKS,
// which is what makes the breakouts 'marginal' and is why the rule was held
// for the tick list. Written as the addendum's 'no more than N ticks' pair:
// strictly beyond (a flat push is not a push) AND within
// maxMinorBreakoutTicks ticks.
//
// The source's 3-to-20-bar pullback between the marginal breakouts is exactly
// what a confirmed pivot at swingStrength already enforces, so it is not
// carried as a second parameter.
//
// THE PIVOT SCAN IS INLINED from ThreePushPattern rather than reaching into
// SwingHigh.json -- rules in this corpus never reference each other, and the
// register lists Occurrence 3 and above as UNMEASURED while the third push is
// the point of the pattern. Measured pivot rule (EL_Swing_Probe.txt /
// el_swing_output1.txt, @ES 60 min): at-or-beyond the swingStrength OLDER
// bars, STRICTLY beyond the swingStrength NEWER ones (bars-ago indexing makes
// the smaller index the newer bar, so the strict half is the k < j loop,
// el_gt/el_lt, and the at-or-beyond half the k > j loop, el_ge/el_le);
// confirmation lag exactly swingStrength bars, hence j from swingStrength;
// candidate offsets 0..Length-1 inclusive, so the deepest bar touched is
// lookbackBars - 1 + swingStrength; the comparisons carry the 2.22e-12
// relational tolerance; -1 SENTINEL on the prices, every use gated on the
// count reaching 3; the low side's tie sense is the mirror of the measured
// high-side rule. No WFSafe_SwingHigh exists, so plain EL governs, and no
// early break is used -- Break is not a registered EasyLanguage word and the
// twins stay statement for statement.
//
// The tick is ctx.MinMove() / ctx.PriceScale(), division-first, both VERIFIED
// and per-symbol constant for the run.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration is a
// redefinition when this rule is placed twice in one strategy. Every one is
// fully assigned each bar before it is read.
tickSize = ctx.MinMove() / ctx.PriceScale();
pivS = (int)swingStrength;
pivW = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
marUp = (nHiPiv == 3) && el_gt(hiPx1 - hiPx2, 0.0) && el_le(hiPx1 - hiPx2, maxMinorBreakoutTicks * tickSize) && el_gt(hiPx2 - hiPx3, 0.0) && el_le(hiPx2 - hiPx3, maxMinorBreakoutTicks * tickSize);
marDn = (nLoPiv == 3) && el_gt(loPx2 - loPx1, 0.0) && el_le(loPx2 - loPx1, maxMinorBreakoutTicks * tickSize) && el_gt(loPx3 - loPx2, 0.0) && el_le(loPx3 - loPx2, maxMinorBreakoutTicks * tickSize);
